// Sorting and the filter of a sheet in the editor: the toolbar buttons, the
// buttons the grid draws in the header cells, the menu that drops down from
// them, and what all of it does to the workbook model. Every workbook is
// generated by code; everything is kept within columns A to D, so that a phone
// shows it as well.
//
// Canvas positions are written out from the default sizes of a sheet: the row
// numbers are 72 px wide, the column letters 22 px high, columns 64 px wide
// and rows 20 px high. The button of a header cell is the 16 px square in its
// bottom right corner.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const HEADER_WIDTH = 72;
const HEADER_HEIGHT = 22;
const COLUMN_WIDTH = 64;
const ROW_HEIGHT = 20;

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;
const str = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t>${text}</t></is></c>`;

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

/**
 * "List": a header and seven rows (row 6 has no colour), an empty row, and a
 * cell further down that does not belong to the block.
 * "Many": 10,300 different values under a header.
 * "Ready": a list that comes with a filter on its second column.
 */
const listWorkbook = once(() => {
  const rows: [string, string | null, number][] = [
    ['Lemon', 'yellow', 40],
    ['Apple', 'red', 10],
    ['Plum', 'purple', 30],
    ['Cherry', 'Red', 5],
    ['Mystery', null, 15],
    ['Banana', 'yellow', 25],
    ['Fig', 'purple', 20],
  ];
  let data = `<row r="1">${str('A1', 'Name')}${str('B1', 'Colour')}${str('C1', 'Amount')}<c r="D1" t="inlineStr"><is><t>Twice</t></is></c></row>`;
  rows.forEach(([name, colour, amount], i) => {
    const r = i + 2;
    data += `<row r="${r}">${str(`A${r}`, name)}${colour ? str(`B${r}`, colour) : ''}${num(`C${r}`, amount)}<c r="D${r}"><f>C${r}*2</f><v>${amount * 2}</v></c></row>`;
  });
  data += `<row r="10">${str('A10', 'apart')}</row>`;
  let many = `<row r="1">${str('A1', 'Id')}</row>`;
  for (let r = 2; r <= 10301; r++) many += `<row r="${r}">${num(`A${r}`, r * 3)}</row>`;
  return buildXlsx({
    sheets: [
      { name: 'List', xml: worksheetXml(`<sheetData>${data}</sheetData>`) },
      { name: 'Many', xml: worksheetXml(`<sheetData>${many}</sheetData>`) },
      {
        name: 'Ready',
        xml: worksheetXml(
          `<sheetData><row r="1">${str('A1', 'Name')}${str('B1', 'Kind')}</row><row r="2">${str('A2', 'a')}${str('B2', 'x')}</row>` +
            `<row r="3" hidden="1">${str('A3', 'b')}${str('B3', 'y')}</row><row r="4">${str('A4', 'c')}${str('B4', 'x')}</row></sheetData>` +
            '<autoFilter ref="A1:B4"><filterColumn colId="1"><filters><filter val="x"/></filters></filterColumn></autoFilter>',
        ),
      },
    ],
  });
});

async function mount(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}, into = 'host'): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options, into }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, into);
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options }, into },
  );
}

const canvas = (page: Page) => page.locator('#host .bym-canvas');

/** A press with the mouse, or a tap, at a point of the canvas. */
async function pressAt(page: Page, hasTouch: boolean | undefined, x: number, y: number, selector = '#host .bym-canvas'): Promise<void> {
  const box = (await page.locator(selector).boundingBox())!;
  if (hasTouch) await page.touchscreen.tap(box.x + x, box.y + y);
  else await page.mouse.click(box.x + x, box.y + y);
}

/** The middle of the filter button of a header cell in row 1 (column 0 is A). */
const buttonOf = (col: number) => ({ x: HEADER_WIDTH + COLUMN_WIDTH * (col + 1) - 9, y: HEADER_HEIGHT + ROW_HEIGHT - 9 });

const select = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    (window as any).__editor.view.select(api.parseRange(ref));
  }, ref);

const settled = (page: Page) => page.evaluate(() => new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve()))));

interface FilterInfo {
  range: string | null;
  columns: { colId: number; kind: string; values?: string[]; blank?: boolean }[];
  sort: string[] | null;
  hidden: number[];
}

const filterInfo = (page: Page, sheet = 0): Promise<FilterInfo> =>
  page.evaluate((sheet) => {
    const api = (window as any).BymOffice;
    const model = (window as any).__editor.view.workbook.sheets[sheet];
    const filter = model.autoFilter;
    const hidden: number[] = [];
    model.rows.forEach((row: any, index: number) => {
      if (row.hidden) hidden.push(index + 1);
    });
    return {
      range: filter ? api.rangeName(filter.range) : null,
      columns: filter ? filter.columns.map((column: any) => ({ colId: column.colId, kind: column.kind, values: column.values, blank: column.blank })) : [],
      sort: filter && filter.sortState ? filter.sortState.conditions.map((c: any) => `${api.rangeName(c.range)}${c.descending ? ' desc' : ''}`) : null,
      hidden: hidden.sort((a, b) => a - b),
    };
  }, sheet);

const columnValues = (page: Page, col: number, top: number, bottom: number, sheet = 0): Promise<unknown[]> =>
  page.evaluate(
    ([col, top, bottom, sheet]) => {
      const api = (window as any).BymOffice;
      const model = (window as any).__editor.view.workbook.sheets[sheet];
      const out: unknown[] = [];
      for (let r = top; r <= bottom; r++) {
        const cell = api.getCell(model, r - 1, col);
        out.push(cell ? (cell.formula ? `=${cell.formula.text}` : cell.value) : null);
      }
      return out;
    },
    [col, top, bottom, sheet],
  );

/** Colour of one canvas pixel (CSS coordinates relative to the canvas) after a forced redraw. */
function pixel(page: Page, x: number, y: number): Promise<number[]> {
  return page.evaluate(
    ([x, y]) => {
      const view = (window as any).__editor.view;
      view.render();
      const element = document.querySelector('#host .bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      return Array.from(element.getContext('2d')!.getImageData(Math.round(x * dpr), Math.round(y * dpr), 1, 1).data).slice(0, 3);
    },
    [x, y],
  );
}

/**
 * A pixel of the left border of a header cell's button, and one inside the button away from its
 * arrow. The border is one CSS pixel wide; 0.3 into it is a device pixel it covers at every ratio.
 */
const borderPixel = (page: Page, col: number) => pixel(page, buttonOf(col).x - 7.7, buttonOf(col).y);
const facePixel = (page: Page, col: number) => pixel(page, buttonOf(col).x - 5.5, buttonOf(col).y - 5.5);
const BORDER = [154, 160, 166];
const WHITE = [255, 255, 255];
const ACTIVE = [26, 127, 69];

const menu = (page: Page) => page.locator('#host .bym-filter');
const rowTexts = (page: Page) => menu(page).locator('.bym-list-row .bym-list-text').allTextContents();
const listRow = (page: Page, text: string) => menu(page).locator('.bym-list-row', { hasText: text });
const message = (page: Page) => page.locator('#host .bym-status-message');
const command = (page: Page, name: string) => page.locator(`#host [data-command="${name}"]`);
const presser = (hasTouch: boolean | undefined) => (target: ReturnType<Page['locator']>) => (hasTouch ? target.tap() : target.click());

/** Switches the filter on over the list and opens the menu of a column. */
async function openMenu(page: Page, hasTouch: boolean | undefined, col: number): Promise<void> {
  const at = buttonOf(col);
  await pressAt(page, hasTouch, at.x, at.y);
  await expect(menu(page)).toBeVisible();
}

async function filterOn(page: Page, ref = 'B3'): Promise<void> {
  await select(page, ref);
  await page.evaluate(() => (window as any).__editor.view.toggleFilter());
  await settled(page);
}

test.describe('the filter button of the toolbar', () => {
  test('switches the filter on over the block around the active cell, draws its buttons, and off again', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook());
    await select(page, 'B3');
    const button = command(page, 'filter');
    await expect(button).toHaveAttribute('aria-pressed', 'false');
    // Nothing there yet: the cell is white.
    expect(await borderPixel(page, 0)).toEqual(WHITE);

    await press(button);
    await settled(page);
    expect(await filterInfo(page)).toEqual({ range: 'A1:D8', columns: [], sort: null, hidden: [] });
    await expect(button).toHaveAttribute('aria-pressed', 'true');
    expect(await borderPixel(page, 0)).toEqual(BORDER);
    expect(await facePixel(page, 0)).toEqual(WHITE);
    expect(await borderPixel(page, 3)).toEqual(BORDER);
    // The name other applications look the range up under.
    expect(await page.evaluate(() => (window as any).__editor.view.workbook.definedNames)).toEqual([{ name: '_xlnm._FilterDatabase', value: 'List!$A$1:$D$8', localSheet: 0, hidden: true }]);

    await press(button);
    await settled(page);
    expect((await filterInfo(page)).range).toBe(null);
    await expect(button).toHaveAttribute('aria-pressed', 'false');
    expect(await borderPixel(page, 0)).toEqual(WHITE);

    // One undo step each.
    await page.evaluate(() => (window as any).__editor.view.undo());
    expect((await filterInfo(page)).range).toBe('A1:D8');
    await settled(page);
    await expect(button).toHaveAttribute('aria-pressed', 'true');
  });

  test('takes a selection of several cells as it is, and says so when there is nothing to filter', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook());
    await select(page, 'A1:B4');
    await press(command(page, 'filter'));
    expect((await filterInfo(page)).range).toBe('A1:B4');
    await press(command(page, 'filter'));
    await select(page, 'C12');
    await press(command(page, 'filter'));
    expect((await filterInfo(page)).range).toBe(null);
    await expect(message(page)).toHaveText('There is no data to filter here');
  });
});

test.describe('the menu of a filter button', () => {
  test('lists the values of its column; choosing some hides the other rows and says how many are left', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook());
    await filterOn(page);
    await openMenu(page, hasTouch, 1);
    await expect(menu(page)).toHaveAttribute('role', 'dialog');
    await expect(menu(page)).toHaveAttribute('aria-label', 'Sort and filter column B');
    expect(await rowTexts(page)).toEqual(['(Select all)', 'purple', 'red', 'yellow', '(Blanks)']);
    // The selection did not move to the header cell.
    expect(await page.evaluate(() => (window as any).BymOffice.rangeName((window as any).__editor.view.selection.range))).toBe('B3');

    const apply = menu(page).locator('[data-action="apply"]');
    await press(listRow(page, '(Select all)'));
    await expect(apply).toBeDisabled();
    await press(listRow(page, 'red'));
    await expect(listRow(page, 'red')).toHaveAttribute('aria-selected', 'true');
    await expect(listRow(page, 'purple')).toHaveAttribute('aria-selected', 'false');
    await expect(menu(page).locator('.bym-list-row[data-kind="all"] .bym-check')).toHaveAttribute('data-state', 'mixed');
    await press(apply);
    await expect(menu(page)).toHaveCount(0);

    // "red" and "Red" are one value; everything else is hidden.
    expect(await filterInfo(page)).toEqual({ range: 'A1:D8', columns: [{ colId: 1, kind: 'values', values: ['red'] }], sort: null, hidden: [2, 4, 6, 7, 8] });
    await expect(message(page)).toHaveText('2 of 7 records shown');
    // The button of the column is the filled one now; its neighbour is not.
    expect(await facePixel(page, 1)).toEqual(ACTIVE);
    expect(await facePixel(page, 0)).toEqual(WHITE);
    expect(await borderPixel(page, 0)).toEqual(BORDER);
    // The message stays while the selection moves, as long as the filter does, and goes with it.
    await page.evaluate(() => (window as any).__editor.view.undo());
    await settled(page);
    await expect(message(page)).toHaveText('');
    await page.evaluate(() => (window as any).__editor.view.redo());
    await settled(page);
    await expect(message(page)).toHaveText('2 of 7 records shown');
    await select(page, 'A1');
    await settled(page);
    await expect(message(page)).toHaveText('2 of 7 records shown');
    // The keyboard is back with the grid.
    expect(await page.evaluate(() => document.activeElement!.className)).toBe('bym-input');

    // The list now shows what is chosen, and can clear the criterion.
    await openMenu(page, hasTouch, 1);
    await expect(listRow(page, 'red')).toHaveAttribute('aria-selected', 'true');
    await expect(listRow(page, 'yellow')).toHaveAttribute('aria-selected', 'false');
    await press(menu(page).locator('[data-action="clear"]'));
    expect((await filterInfo(page)).hidden).toEqual([]);
    expect((await filterInfo(page)).columns).toEqual([]);
    await settled(page);
    await expect(message(page)).toHaveText('');

    // Undo brings the criterion and the hidden rows back in one step.
    await page.evaluate(() => (window as any).__editor.view.undo());
    expect((await filterInfo(page)).hidden).toEqual([2, 4, 6, 7, 8]);
  });

  test('another column only offers what the first one shows; blanks can be chosen', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook());
    await filterOn(page);
    await openMenu(page, hasTouch, 1);
    await press(listRow(page, 'purple'));
    await press(listRow(page, 'red'));
    await press(menu(page).locator('[data-action="apply"]'));
    expect(await filterInfo(page)).toEqual({ range: 'A1:D8', columns: [{ colId: 1, kind: 'values', values: ['yellow'], blank: true }], sort: null, hidden: [3, 4, 5, 8] });

    await openMenu(page, hasTouch, 0);
    expect(await rowTexts(page)).toEqual(['(Select all)', 'Banana', 'Lemon', 'Mystery']);
    await press(menu(page).locator('[data-action="cancel"]'));
    await expect(menu(page)).toHaveCount(0);
    expect((await filterInfo(page)).hidden).toEqual([3, 4, 5, 8]);
  });

  test('the search narrows the list, and Apply then shows what was found', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook());
    await filterOn(page);
    await openMenu(page, hasTouch, 0);
    const search = menu(page).locator('.bym-panel-search');
    await search.fill('E');
    // Case does not matter; blanks are not offered while searching.
    expect(await rowTexts(page)).toEqual(['(Select all)', 'Apple', 'Cherry', 'Lemon', 'Mystery']);
    await search.fill('zzz');
    await expect(menu(page).locator('.bym-panel-empty')).toHaveText('Nothing matches');
    await expect(menu(page).locator('[data-action="apply"]')).toBeDisabled();
    await search.fill('an');
    expect(await rowTexts(page)).toEqual(['(Select all)', 'Banana']);
    await press(menu(page).locator('[data-action="apply"]'));
    expect(await filterInfo(page)).toEqual({ range: 'A1:D8', columns: [{ colId: 0, kind: 'values', values: ['Banana'] }], sort: null, hidden: [2, 3, 4, 5, 6, 8] });
  });

  test('sorts by its column: the header stays, formulas follow their rows, and the sort is noted in the filter', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook());
    await filterOn(page);
    await openMenu(page, hasTouch, 0);
    await press(menu(page).locator('[data-action="sort-desc"]'));
    await expect(menu(page)).toHaveCount(0);
    expect(await columnValues(page, 0, 1, 8)).toEqual(['Name', 'Plum', 'Mystery', 'Lemon', 'Fig', 'Cherry', 'Banana', 'Apple']);
    expect(await columnValues(page, 2, 1, 8)).toEqual(['Amount', 30, 15, 40, 20, 5, 25, 10]);
    expect(await columnValues(page, 3, 1, 4)).toEqual(['Twice', '=C2*2', '=C3*2', '=C4*2']);
    expect((await filterInfo(page)).sort).toEqual(['A2:A8 desc']);
    // The cell outside the block stayed where it was.
    expect(await columnValues(page, 0, 10, 10)).toEqual(['apart']);

    await openMenu(page, hasTouch, 2);
    await press(menu(page).locator('[data-action="sort-asc"]'));
    expect(await columnValues(page, 2, 1, 8)).toEqual(['Amount', 5, 10, 15, 20, 25, 30, 40]);
    expect((await filterInfo(page)).sort).toEqual(['C2:C8']);
    // The results of the moved formulas are those of their new rows.
    expect(
      await page.evaluate(() => {
        const api = (window as any).BymOffice;
        const model = (window as any).__editor.view.workbook.sheets[0];
        return [1, 2, 7].map((r) => api.getCell(model, r, 3).value);
      }),
    ).toEqual([10, 20, 80]);

    await page.evaluate(() => (window as any).__editor.view.undo());
    expect(await columnValues(page, 0, 1, 8)).toEqual(['Name', 'Plum', 'Mystery', 'Lemon', 'Fig', 'Cherry', 'Banana', 'Apple']);
    await page.evaluate(() => (window as any).__editor.view.undo());
    expect(await columnValues(page, 0, 1, 8)).toEqual(['Name', 'Lemon', 'Apple', 'Plum', 'Cherry', 'Mystery', 'Banana', 'Fig']);
    expect((await filterInfo(page)).sort).toBe(null);
  });

  test('works with the keyboard: Alt+Down opens it, arrows and Space choose, Enter applies, Escape closes', async ({ page }) => {
    await mount(page, await listWorkbook());
    await filterOn(page);
    await select(page, 'B1');
    await page.evaluate(() => (window as any).__editor.view.focus());
    await page.keyboard.press('Alt+ArrowDown');
    await expect(menu(page)).toBeVisible();
    const list = menu(page).locator('.bym-list');
    await expect(list).toBeFocused();
    const active = () => menu(page).locator('.bym-list-row[data-active] .bym-list-text').textContent();
    expect(await active()).toBe('(Select all)');
    // The list names its active row for assistive technology.
    const id = await list.getAttribute('aria-activedescendant');
    expect(await page.evaluate((id) => document.getElementById(id!)!.textContent, id)).toBe('(Select all)');

    await page.keyboard.press('Space');
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('ArrowDown');
    expect(await active()).toBe('yellow');
    await page.keyboard.press('Space');
    await page.keyboard.press('End');
    expect(await active()).toBe('(Blanks)');
    await page.keyboard.press('Home');
    expect(await active()).toBe('(Select all)');
    await page.keyboard.press('Enter');
    await expect(menu(page)).toHaveCount(0);
    expect((await filterInfo(page)).columns).toEqual([{ colId: 1, kind: 'values', values: ['yellow'] }]);
    expect(await page.evaluate(() => document.activeElement!.className)).toBe('bym-input');

    // Escape closes without changing anything; Tab stays inside the menu.
    await page.keyboard.press('Alt+ArrowDown');
    await expect(list).toBeFocused();
    await page.keyboard.press('Tab');
    await expect(menu(page).locator('[data-action="apply"]')).toBeFocused();
    await page.keyboard.press('Tab');
    await page.keyboard.press('Tab');
    await expect(menu(page).locator('[data-action="sort-asc"]')).toBeFocused();
    await page.keyboard.press('Shift+Tab');
    await expect(menu(page).locator('[data-action="cancel"]')).toBeFocused();
    await page.keyboard.press('Escape');
    await expect(menu(page)).toHaveCount(0);
    expect((await filterInfo(page)).columns).toEqual([{ colId: 1, kind: 'values', values: ['yellow'] }]);
    expect(await page.evaluate(() => document.activeElement!.className)).toBe('bym-input');
    // Alt+Down anywhere else does nothing.
    await select(page, 'B2');
    await page.keyboard.press('Alt+ArrowDown');
    await expect(menu(page)).toHaveCount(0);
  });

  test('a press outside closes it, and so does scrolling the grid', async ({ page, hasTouch }) => {
    await mount(page, await listWorkbook());
    await filterOn(page);
    await openMenu(page, hasTouch, 0);
    await (hasTouch ? page.locator('#after').tap() : page.locator('#after').click());
    await expect(menu(page)).toHaveCount(0);
    await openMenu(page, hasTouch, 0);
    await page.evaluate(() => (document.querySelector('#host .bym-scroller') as HTMLElement).scrollTo(0, 200));
    await expect(menu(page)).toHaveCount(0);
  });

  test('speaks Turkish with a Turkish locale', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook(), { locale: 'tr' });
    await expect(command(page, 'filter')).toHaveAttribute('aria-label', 'Süzgeç');
    await expect(command(page, 'sortAscending')).toHaveAttribute('aria-label', "A'dan Z'ye sırala");
    await filterOn(page);
    await openMenu(page, hasTouch, 1);
    await expect(menu(page)).toHaveAttribute('aria-label', 'B sütununu sırala ve süz');
    expect(await rowTexts(page)).toEqual(['(Tümünü seç)', 'purple', 'red', 'yellow', '(Boşlar)']);
    await expect(menu(page).locator('[data-action="sort-asc"]')).toHaveText("A'dan Z'ye sırala");
    await expect(menu(page).locator('[data-action="clear"]')).toHaveText('Süzgeci temizle');
    await press(listRow(page, 'yellow'));
    await press(menu(page).locator('[data-action="apply"]'));
    await expect(message(page)).toHaveText('7 kayıttan 5 tanesi gösteriliyor');
  });

  test('a column with more values than the list holds shows the first ten thousand, a few rows at a time', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook(), { sheet: 1 });
    await filterOn(page, 'A2');
    expect((await filterInfo(page, 1)).range).toBe('A1:A10301');
    const started = Date.now();
    await openMenu(page, hasTouch, 0);
    expect(Date.now() - started).toBeLessThan(5000);
    await expect(menu(page).locator('[role="note"]')).toHaveText('Only the first 10000 values are listed');
    // Only the rows in sight exist.
    expect(await menu(page).locator('.bym-list-row').count()).toBeLessThan(40);
    const list = menu(page).locator('.bym-list');
    await list.evaluate((element) => (element.scrollTop = element.scrollHeight));
    await expect(listRow(page, '30003')).toBeVisible();
    expect(await menu(page).locator('.bym-list-row').count()).toBeLessThan(40);
    await press(listRow(page, '30003'));
    await press(menu(page).locator('[data-action="apply"]'));
    const info = await filterInfo(page, 1);
    expect(info.columns[0].values!.length).toBe(9999);
    // The value that was taken out, and the 300 that the list did not hold.
    expect(info.hidden.length).toBe(301);
    await expect(message(page)).toHaveText('9999 of 10300 records shown');
  });

  test('stays inside a narrow editor and can still be used there', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook());
    await page.evaluate(() => {
      const host = document.getElementById('host')!;
      host.style.width = '300px';
      host.style.height = '330px';
    });
    await settled(page);
    await filterOn(page);
    await openMenu(page, hasTouch, 2);
    const box = (await menu(page).boundingBox())!;
    const host = (await page.locator('#host .bym-view').boundingBox())!;
    expect(box.x).toBeGreaterThanOrEqual(host.x);
    expect(box.x + box.width).toBeLessThanOrEqual(host.x + host.width + 0.5);
    expect(box.y).toBeGreaterThanOrEqual(host.y);
    expect(box.y + box.height).toBeLessThanOrEqual(host.y + host.height + 0.5);
    const apply = menu(page).locator('[data-action="apply"]');
    await apply.scrollIntoViewIfNeeded();
    await press(listRow(page, '(Select all)'));
    await menu(page).locator('.bym-list').evaluate((element) => (element.scrollTop = 0));
    await press(listRow(page, '10'));
    await apply.scrollIntoViewIfNeeded();
    await press(apply);
    expect((await filterInfo(page)).hidden).toEqual([2, 4, 5, 6, 7, 8]);
  });

  test('works inside a shadow root and under a CSS transform', async ({ page, hasTouch }) => {
    await mount(page, await listWorkbook(), {}, 'shadow-open');
    await page.evaluate(() => {
      const host = document.getElementById('shadowhost')!;
      host.style.transform = 'scale(0.8)';
      host.style.transformOrigin = '0 0';
      (window as any).__editor.view.render();
    });
    await select(page, 'B3');
    await page.evaluate(() => (window as any).__editor.view.toggleFilter());
    const box = (await page.locator('#shadowhost .bym-canvas').boundingBox())!;
    const at = buttonOf(1);
    const x = box.x + at.x * 0.8;
    const y = box.y + at.y * 0.8;
    if (hasTouch) await page.touchscreen.tap(x, y);
    else await page.mouse.click(x, y);
    const shadowMenu = page.locator('#shadowhost .bym-filter');
    await expect(shadowMenu).toBeVisible();
    // A press on a row is a press inside the menu, although the page only sees the shadow host.
    const row = shadowMenu.locator('.bym-list-row', { hasText: 'purple' });
    await (hasTouch ? row.tap() : row.click());
    await expect(shadowMenu).toBeVisible();
    await expect(row).toHaveAttribute('aria-selected', 'false');
    const apply = shadowMenu.locator('[data-action="apply"]');
    await (hasTouch ? apply.tap() : apply.click());
    expect((await filterInfo(page)).hidden).toEqual([4, 8]);
    // A press beside the editor closes a menu that is open.
    if (hasTouch) await page.touchscreen.tap(x, y);
    else await page.mouse.click(x, y);
    await expect(shadowMenu).toBeVisible();
    await (hasTouch ? page.locator('#before').tap() : page.locator('#before').click());
    await expect(shadowMenu).toHaveCount(0);
  });
});

test.describe('sorting from the toolbar', () => {
  test('sorts the block around the active cell by its column and keeps the first row as the header', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook());
    await select(page, 'C4');
    await press(command(page, 'sortAscending'));
    expect(await columnValues(page, 2, 1, 8)).toEqual(['Amount', 5, 10, 15, 20, 25, 30, 40]);
    expect(await columnValues(page, 0, 1, 8)).toEqual(['Name', 'Cherry', 'Apple', 'Mystery', 'Fig', 'Banana', 'Plum', 'Lemon']);
    await press(command(page, 'sortDescending'));
    expect(await columnValues(page, 2, 1, 8)).toEqual(['Amount', 40, 30, 25, 20, 15, 10, 5]);
    // Text: without regard to case, the empty cell last in both directions.
    await select(page, 'B2');
    await press(command(page, 'sortAscending'));
    expect(await columnValues(page, 1, 1, 8)).toEqual(['Colour', 'purple', 'purple', 'red', 'Red', 'yellow', 'yellow', null]);
    await press(command(page, 'sortDescending'));
    expect(await columnValues(page, 1, 1, 8)).toEqual(['Colour', 'yellow', 'yellow', 'red', 'Red', 'purple', 'purple', null]);
    // A selection of several cells is sorted as it is, without a header.
    await select(page, 'C2:C4');
    await press(command(page, 'sortAscending'));
    const sorted = (await columnValues(page, 2, 2, 4)) as number[];
    expect(sorted).toEqual(sorted.slice().sort((a, b) => a - b));
    expect((await columnValues(page, 2, 1, 1))[0]).toBe('Amount');
  });

  test('a range with merged cells is refused with a message', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook());
    await select(page, 'A3:B3');
    await page.evaluate(() => (window as any).__editor.view.merge());
    await select(page, 'C4');
    await press(command(page, 'sortAscending'));
    await expect(message(page)).toHaveText('A range with merged cells cannot be sorted');
    expect(await columnValues(page, 2, 1, 3)).toEqual(['Amount', 40, 10]);
  });
});

test.describe('a filter that comes with the file', () => {
  test('shows its buttons and its count, and is written back with what was changed', async ({ page, hasTouch }) => {
    const press = presser(hasTouch);
    await mount(page, await listWorkbook(), { sheet: 2 });
    await settled(page);
    expect(await filterInfo(page, 2)).toEqual({ range: 'A1:B4', columns: [{ colId: 1, kind: 'values', values: ['x'] }], sort: null, hidden: [3] });
    await expect(message(page)).toHaveText('2 of 3 records shown');
    await expect(command(page, 'filter')).toHaveAttribute('aria-pressed', 'true');
    expect(await facePixel(page, 1)).toEqual(ACTIVE);

    await openMenu(page, hasTouch, 1);
    await expect(listRow(page, 'x')).toHaveAttribute('aria-selected', 'true');
    await expect(listRow(page, 'y')).toHaveAttribute('aria-selected', 'false');
    await press(listRow(page, 'x'));
    await press(listRow(page, 'y'));
    await press(menu(page).locator('[data-action="apply"]'));
    expect((await filterInfo(page, 2)).hidden).toEqual([2, 4]);

    const reopened = await page.evaluate(async () => {
      const api = (window as any).BymOffice;
      const saved = await (window as any).__file.save();
      const workbook = await (await api.open(saved)).workbook();
      const sheet = workbook.sheets[2];
      const hidden: number[] = [];
      sheet.rows.forEach((row: any, index: number) => {
        if (row.hidden) hidden.push(index + 1);
      });
      return { range: api.rangeName(sheet.autoFilter.range), values: sheet.autoFilter.columns[0].values, hidden: hidden.sort(), names: workbook.definedNames.map((name: any) => `${name.name}=${name.value}`) };
    });
    expect(reopened).toEqual({ range: 'A1:B4', values: ['y'], hidden: [2, 4], names: ['_xlnm._FilterDatabase=Ready!$A$1:$B$4'] });
  });
});

test.describe('read-only', () => {
  test('the buttons are drawn but do nothing, and the toolbar is off', async ({ page, hasTouch }) => {
    await mount(page, await listWorkbook(), { sheet: 2, readOnly: true });
    await settled(page);
    for (const name of ['filter', 'sortAscending', 'sortDescending']) await expect(command(page, name)).toBeDisabled();
    expect(await facePixel(page, 1)).toEqual(ACTIVE);
    const at = buttonOf(1);
    await pressAt(page, hasTouch, at.x, at.y);
    await expect(menu(page)).toHaveCount(0);
    // The press selected the cell instead.
    expect(await page.evaluate(() => (window as any).BymOffice.rangeName((window as any).__editor.view.selection.range))).toBe('B1');
    await page.evaluate(() => {
      const view = (window as any).__editor.view;
      view.toggleFilter();
      view.sort(false);
      view.setColumnFilter(1, undefined);
    });
    expect(await filterInfo(page, 2)).toEqual({ range: 'A1:B4', columns: [{ colId: 1, kind: 'values', values: ['x'] }], sort: null, hidden: [3] });
    expect(await page.evaluate(() => (window as any).__editor.view.openFilterMenu(1))).toBe(false);
  });
});

